const goldenMintMonitor = `sudo -u postgres psql -p 5432 -w -v ON_ERROR_STOP=1 <<'INFORGE_PGSQL'
DO $$
BEGIN
  IF NOT EXISTS (SELECT FROM pg_roles WHERE rolname = 'ROLE') THEN
    CREATE ROLE "ROLE" LOGIN PASSWORD 'PASSWORD';
  ELSE
    ALTER ROLE "ROLE" WITH LOGIN PASSWORD 'PASSWORD';
  END IF;
END
$$;
GRANT pg_monitor TO "ROLE";
GRANT CONNECT ON DATABASE "DB1" TO "ROLE";
GRANT CONNECT ON DATABASE "DB2" TO "ROLE";
INFORGE_PGSQL`
